const SECRET = "kuchinskaya_secret_key_2026";
const VALID_USER = "student";
const VALID_PASS = "lab2secret";
const EXPIRES_IN = 3600;

function base64url(str) {
    return Buffer.from(str).toString("base64")
        .replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
}

function simpleSign(data, secret) {
    const combined = data + "." + secret;
    return base64url(combined.split("").reverse().join(""));
}

function createJWT(payload, secret, expiresIn) {
    const header = { alg: "HS256", typ: "JWT" };
    const now = Math.floor(Date.now() / 1000);
    const fullPayload = Object.assign({}, payload, { iat: now, exp: now + expiresIn });
    const headerB64 = base64url(JSON.stringify(header));
    const payloadB64 = base64url(JSON.stringify(fullPayload));
    const signature = simpleSign(headerB64 + "." + payloadB64, secret);
    return headerB64 + "." + payloadB64 + "." + signature;
}

const body = msg.payload || {};

if (body.username === VALID_USER && body.password === VALID_PASS) {
    const token = createJWT({ username: body.username }, SECRET, EXPIRES_IN);
    msg.statusCode = 200;
    msg.payload = {
        success: true,
        token: token,
        expiresIn: EXPIRES_IN,
        tokenType: "Bearer"
    };
} else {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Неверный логин или пароль" };
}

return msg;

const SECRET = "kuchinskaya_secret_key_2026";

function base64urlDecode(str) {
    str = str.replace(/-/g, "+").replace(/_/g, "/");
    while (str.length % 4) str += "=";
    return Buffer.from(str, "base64").toString("utf8");
}

function base64url(str) {
    return Buffer.from(str).toString("base64")
        .replace(/=/g, "").replace(/\+/g, "-").replace(/\//g, "_");
}

function simpleSign(data, secret) {
    const combined = data + "." + secret;
    return base64url(combined.split("").reverse().join(""));
}

const authHeader = msg.req.headers["authorization"] || "";

if (!authHeader.startsWith("Bearer ")) {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Нет токена. Заголовок: Authorization: Bearer <token>" };
    return msg;
}

const token = authHeader.substring(7);
const parts = token.split(".");

if (parts.length !== 3) {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Неверный формат JWT" };
    return msg;
}

const headerB64 = parts[0];
const payloadB64 = parts[1];
const signature = parts[2];

const expectedSig = simpleSign(headerB64 + "." + payloadB64, SECRET);
if (expectedSig !== signature) {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Неверная подпись токена" };
    return msg;
}

let payload;
try {
    payload = JSON.parse(base64urlDecode(payloadB64));
} catch (e) {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Не удалось декодировать payload" };
    return msg;
}

const now = Math.floor(Date.now() / 1000);
if (payload.exp < now) {
    msg.statusCode = 401;
    msg.payload = { success: false, error: "Токен истёк", expiredAt: payload.exp, now: now };
    return msg;
}

msg.statusCode = 200;
msg.payload = {
    success: true,
    user: {
        username: payload.username,
        issuedAt: payload.iat,
        expiresAt: payload.exp
    },
    message: "Доступ разрешён. JWT валиден."
};

return msg;
